<?phpnamespace app\store\controller\shop;use app\store\controller\Controller;use app\store\model\Qrcode as QrcodeModel;use app\store\model\Table as TableModel;use think\facade\View;/** * 二维码控制器 */class Qrcode extends Controller{     /**     * 列表     */    public function index()    {        $model = new QrcodeModel;        $list = $model->getList();        return View::fetch('index', compact('list'));    }        /**     * 添加     */    public function add()    {        if ($this->request->isPost()) {            $model = new QrcodeModel;            if ($model->add($this->postData('data'))) {                return $this->renderSuccess('添加成功', url('shop.qrcode/index'));            }            $error = $model->getError() ?: '添加失败';            return $this->renderError($error);        }        return redirect(url('shop.qrcode/index'));    }        /**     * 编辑     */    public function edit(int $id)    {        // 详情        $model = QrcodeModel::detail($id);        if (!$this->request->isAjax()) {            $tableModel = new TableModel;            $table = $tableModel->getList(false);//获取餐桌列表            return View::fetch('edit', compact('model','table'));        }        // 更新记录        if ($model->edit($this->postData('data'))) {            return $this->renderSuccess('操作成功', url('shop.qrcode/index'));        }        $error = $model->getError() ?: '操作失败';        return $this->renderError($error);    }        /**     * 删除     */    public function delete()    {        $data = $this->postData();        $model = QrcodeModel::get($data['id']);        if($model->remove()) {            return $this->renderSuccess('删除成功');        }        $error = $model->getError() ?: '删除失败';        return $this->renderError($error);    }}